                        .HasColumnType("bigint");

                    b.HasKey("Id");

                    b.HasAlternateKey("CompanyId", "Id");

                    b.HasIndex("CompanyId");

                    b.HasIndex("DepartmentId");

                    b.HasIndex("DesignationId");

                    b.HasIndex("EmployeeCompanyAssignmentId")
