                            t.HasCheckConstraint("CK_notification_event_timestamps", "(\"Status\" IN ('SCHEDULED','READY') AND \"ActivatedAt\" IS NULL AND \"CompletedAt\" IS NULL AND \"CancelledAt\" IS NULL AND \"CancelledBy\" IS NULL AND \"CancellationReason\" IS NULL) OR (\"Status\" IN ('ACTIVE','RECIPIENT_BLOCKED') AND \"ActivatedAt\" IS NOT NULL AND \"CompletedAt\" IS NULL AND \"CancelledAt\" IS NULL AND \"CancelledBy\" IS NULL AND \"CancellationReason\" IS NULL) OR (\"Status\"='COMPLETED' AND \"ActivatedAt\" IS NOT NULL AND \"CompletedAt\" IS NOT NULL AND \"CancelledAt\" IS NULL AND \"CancelledBy\" IS NULL AND \"CancellationReason\" IS NULL) OR (\"Status\"='CANCELLED' AND \"CompletedAt\" IS NULL AND \"CancelledAt\" IS NOT NULL AND length(trim(coalesce(\"CancelledBy\",'')))>0 AND length(trim(coalesce(\"CancellationReason\",'')))>0)");
                        });
                });

